                    nav_label, nav_order, in_header, in_footer, sections, build_status)
VALUES (gen_random_uuid(), '4851f6fc-71cf-4160-a270-e03d6d3e0732',
        'ai-data-trust-in-hiring-and-hr',
        '/blog/ai-data-trust-in-hiring-and-hr.html',
        'AI in Hiring: The Widest Trust Gap We Found in Any Sector | Leopardess Consulting',
        'blog-post', 'active',
        '70%% of hiring managers trust AI hiring decisions. Only 8%% of job seekers call it fair. The widest trust gap in this research, cited and quoted.',
